<style>
.preview-shell{padding:clamp(1rem,3vw,2.5rem);background:linear-gradient(135deg,#eef1f7,#f9fafc);overflow:auto}.training-id-card{position:relative;width:min(100%,460px);aspect-ratio:9.2/12.4;margin:auto;overflow:hidden;border-radius:20px;background:var(--card-primary);color:var(--card-text);box-shadow:0 18px 45px rgba(35,45,80,.22);font-family:Arial,sans-serif}.training-id-card__background{position:absolute;inset:0;background-position:center;background-size:cover;opacity:var(--card-opacity)}.training-id-card__background:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,color-mix(in srgb,var(--card-primary) 80%,transparent),color-mix(in srgb,var(--card-primary) 48%,transparent))}.training-id-card__shape{position:absolute;border-radius:50%;background:var(--card-accent);opacity:.9}.shape-one{width:55%;aspect-ratio:1;right:-30%;top:-18%}.shape-two{width:35%;aspect-ratio:1;left:-20%;bottom:-12%;opacity:.32}.training-id-card__content{position:relative;z-index:2;display:flex;flex-direction:column;height:100%;padding:7% 8% 6%}.training-id-card header{display:flex;flex-direction:column;align-items:center;gap:2.5%;min-height:28%;text-align:center}.training-id-card__logo{display:grid;place-items:center;width:43.48%;aspect-ratio:2/1;color:var(--card-text);font-size:2.3rem}.training-id-card__logo img{width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 3px 6px rgba(0,0,0,.18))}.training-id-card header span{display:block;margin-top:.45rem;font-size:clamp(.52rem,1.7vw,.72rem);font-weight:700;letter-spacing:.18em;opacity:.84}.training-id-card header strong{display:block;max-width:390px;margin-top:.28rem;font-size:clamp(.72rem,2.5vw,1.05rem);line-height:1.22;text-transform:uppercase}.training-id-card main{display:flex;flex:1;flex-direction:column;align-items:center;justify-content:center;gap:4%;min-height:0;padding:3% 2%}.training-id-card__photo{flex:0 0 auto;width:37%;aspect-ratio:3/4;border:5px solid rgba(255,255,255,.97);border-radius:13px;background:#e7eaf0;overflow:hidden;box-shadow:0 10px 28px rgba(0,0,0,.25)}.training-id-card__photo img{width:100%;height:100%;object-fit:cover}.photo-empty{display:grid;place-content:center;height:100%;color:#8993a4;text-align:center}.photo-empty i{font-size:3rem}.photo-empty small{font-size:.65rem}.training-id-card__identity{width:100%;min-width:0;text-align:center;text-shadow:0 2px 6px rgba(0,0,0,.22)}.training-id-card__identity small{font-size:clamp(.48rem,1.5vw,.64rem);font-weight:700;letter-spacing:.22em;opacity:.82}.training-id-card__identity h2{margin:.35rem 0 .5rem;color:var(--card-text);font-size:clamp(.95rem,4vw,1.65rem);line-height:1.08;text-transform:uppercase;overflow-wrap:anywhere}.identity-line{width:48px;height:4px;margin:0 auto .55rem;border-radius:5px;background:var(--card-accent)}.training-id-card__identity p{margin:.14rem 0;font-size:clamp(.52rem,1.75vw,.73rem);line-height:1.25}.training-id-card footer{display:flex;justify-content:space-between;gap:.7rem;padding-top:3.5%;border-top:1px solid rgba(255,255,255,.3);font-size:clamp(.44rem,1.45vw,.62rem)}.training-id-card footer span{display:flex;align-items:flex-start;gap:.3rem;max-width:49%}.training-id-card footer span:last-child{justify-content:flex-end;text-align:right}.identity-settings-page .form-control-color{height:42px}@media(max-width:575px){.training-id-card{border-radius:12px}.training-id-card__content{padding:6% 7% 5%}.training-id-card__photo{border-width:3px}.training-id-card footer{font-size:.43rem}}
</style>